def create_stairs(conn_header: ConnHeader, params: CreateStairsParameters) -> dict:
    """
    Creates Stair elements based on the given baseline and parameters, optionally with the segment type of each baseline
    edge and the turn at each baseline point (landings and winders), and with curved baseline edges (baseLineArcs) for
    curved and spiral stairs. Accepts the same settings as ModifyStairs: the step values with their locks, the top link
    (relativeTopStory, topOffset), the Rules and Standards, the headroom, the finish and structure visibility, the extra
    treads, the walking line, the numbering, the walking direction, and the tread, riser and structure settings of the
    flights and the landings (with the monolith data of a Monolith structure and the stringer data of a Side one), and
    the floor plan and reflected ceiling plan display (shown stories and components, the symbol on each story, the break
    line and the line type, pen and fill overrides), and the line types, pens and fills of the structure symbols
    (structureSymbols, monolithStructureSymbols) with their visibility on the stories (structureVisibilityOnStories);
    settings not given come from the Stair tool defaults or the favorite. Archicad lays out the boundaries and the
    walking lines from the baseline and the flight width, and the API cannot write them: an item that gives one is
    refused with an error that says so.
    """
    return conn_header.core.post_tapir_command(
        command="CreateStairs", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


