def create_zones(conn_header: ConnHeader, params: CreateZonesParameters) -> dict:
    """
    Creates Zone elements based on the given parameters. Takes the same zone settings as ModifyZones (name, number,
    category, zone stamp, stamp pen, levels, letter size (roomLSize, in millimetres), contour line, cover fill, 3D
    surface, polygon display and area reduction), applied by the same helpers; the polygon or reference point, and the
    layer (layerIndex), are only set here. An item whose area would overlap an existing Zone on the same story fails
    with an error naming that Zone instead of opening Archicad's modal overlap warning, unless its allowOverlap is true.
    """
    return conn_header.core.post_tapir_command(
        command="CreateZones", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


